import React, { useState } from "react";
import { Link, useNavigate, useParams } from "react-router-dom";
import { useApp } from "../../lib/AppContext";
import { officers, statuses, formatLabel } from "../../lib/reportData";
import SeverityBadge from "../ui/SeverityBadge";
import StatusBadge from "../ui/StatusBadge";
const ReportDetailModal = () => {
  const {
    id
  } = useParams();
  const navigate = useNavigate();
  const {
    reports,
    updateReport,
    notify
  } = useApp();
  const report = reports.find(item => item.id === id);
  const [note, setNote] = useState("");
  const [notes, setNotes] = useState([]);
  if (!report) return <div className="empty-page">
        <h2>Report not found</h2>
        <button className="secondary" onClick={() => navigate("/reports")}>
          Back to reports
        </button>
      </div>;
  const saveNote = () => {
    if (!note.trim()) return;
    setNotes(current => [{
      text: note.trim(),
      time: new Date().toLocaleString()
    }, ...current]);
    setNote("");
    notify("Progress note added to case timeline");
  };
  return <div className="overlay" onMouseDown={event => event.target === event.currentTarget && navigate("/reports")}>
      <section className="detail-drawer">
        <div className="drawer-head">
          <div>
            <span className="eyebrow">CASE FILE</span>
            <h2>{report.id}</h2>
          </div>
          <button className="icon-button" onClick={() => navigate("/reports")}>
            ×
          </button>
        </div>
        <div className="drawer-scroll">
          <div className="detail-pills">
            <SeverityBadge severity={report.severity} />
            <StatusBadge status={report.status} />
          </div>
          <h3>{report.category}</h3>
          <p className="detail-desc">{report.description}</p>
          {report.image && <img className="evidence" src={report.image} alt="Citizen submitted evidence" />}
          <div className="media-strip">
            <button onClick={() => notify("Image evidence opened")}>
              ▧ View image evidence
            </button>
            <button onClick={() => notify("No audio evidence attached")}>
              ♫ Audio
            </button>
            <button onClick={() => notify("No video evidence attached")}>
              ▷ Video
            </button>
          </div>
          <div className="detail-grid">
            <div>
              <small>LOCATION</small>
              <b>⌖ {report.location}</b>
            </div>
            <div>
              <small>SUBMITTED</small>
              <b>{report.date}</b>
            </div>
            <div>
              <small>REPORTED BY</small>
              <b>{report.reporter}</b>
            </div>
            <div>
              <small>COORDINATES</small>
              <b>
                {report.lat}, {report.lon}
              </b>
            </div>
          </div>
          <label className="field-label" htmlFor="case-status">
            Case status
          </label>
          <select id="case-status" value={report.status} onChange={event => {
          updateReport(report.id, {
            status: event.target.value
          });
          notify("Case status updated");
        }}>
            {statuses.map(value => <option key={value} value={value}>
                {formatLabel(value)}
              </option>)}
          </select>
          <label className="field-label" htmlFor="assigned-officer">
            Assigned officer
          </label>
          <select id="assigned-officer" value={report.officer} onChange={event => {
          updateReport(report.id, {
            officer: event.target.value
          });
          notify("Officer assignment updated");
        }}>
            {officers.map(officer => <option key={officer}>{officer}</option>)}
          </select>
          <div className="timeline-title">
            <h3>Case timeline</h3>
            <span>Latest activity</span>
          </div>
          <div className="timeline">
            {notes.map((item, index) => <div className="timeline-item" key={`${item.time}-${index}`}>
                <i />
                <b>Progress update</b>
                <small>
                  {item.text} · {item.time}
                </small>
              </div>)}
            <div className="timeline-item">
              <i />
              <b>Report submitted</b>
              <small>
                {report.date} · by {report.reporter}
              </small>
            </div>
            <div className="timeline-item">
              <i />
              <b>Case received by NEMA</b>
              <small>Automated update · today</small>
            </div>
          </div>
          <label className="field-label" htmlFor="progress-note">
            Add progress note
          </label>
          <textarea id="progress-note" value={note} onChange={event => setNote(event.target.value)} placeholder="Share an update with the case record…" />
          <button className="primary full" onClick={saveNote}>
            Post update <span>→</span>
          </button>
          <Link className="secondary full chat-link" to={`/reports/${report.id}/chat`}>
            ◉ Open citizen chat
          </Link>
        </div>
      </section>
    </div>;
};
export default ReportDetailModal;
